            std::fprintf(stderr, "strata generate: --batch %d: the slot sessions take %.2f GiB of VRAM on CUDA0 that the "
                                 "expert cache would otherwise hold\n", o.batch,
                         (double) bytes0 * o.batch / 1073741824.0);
        }
    }

